// Overrides at three depths; the middle class calls super.end(x) with a typed value while the
// base calls this.end(x) with a different type.
class Base {
  end(x) { return "B:" + typeof x; }
  go(v) { return this.end(v) + "/" + this.end(); }
}
class Mid extends Base {
  end(x) { return "M(" + super.end(x) + ")"; }
}
class Leaf extends Mid {
  end(x, y) { return "L(" + super.end(x) + "," + y + ")"; }
}
/** @returns {Base} */
function pick(i) {
  return i === 0 ? new Base() : i === 1 ? new Mid() : new Leaf();
}
module.exports = { Base, Mid, Leaf, pick };
